defense.vulnerable_config:
# Node.js / Express — BOLA vulnerability:
app.get('/api/v1/users/:id/profile', authenticate, async (req, res) => {
  // VULNERABLE: checks token is valid, but NOT that req.params.id == req.user.id
  const user = await db.query('SELECT * FROM users WHERE id = ?', [req.params.id])
  if (!user) return res.status(404).json({error:'not found'})
  res.json(user)  // returns ANY user's profile to any authenticated token
})

# Python Flask — same pattern:
@app.route('/api/v1/orders/<int:order_id>')
@jwt_required()
def get_order(order_id):
  order = Order.query.get(order_id)  # VULNERABLE: no ownership check
  return jsonify(order.to_dict())

# Sequential ID generation:
CREATE TABLE orders (id SERIAL PRIMARY KEY, ...)  -- attacker iterates 1,2,3...

defense.secure_config:
# Node.js — ownership enforced server-side:
app.get('/api/v1/users/:id/profile', authenticate, async (req, res) => {
  // SAFE: only allow access to own profile (or admin role)
  if (req.params.id !== req.user.id && req.user.role !== 'admin') {
    return res.status(403).json({error: 'Forbidden'})
  }
  const user = await db.query('SELECT id,name,email FROM users WHERE id = ?', [req.params.id])
  res.json(user)
})

# Python Flask — ownership in query:
@app.route('/api/v1/orders/<int:order_id>')
@jwt_required()
def get_order(order_id):
  current_uid = get_jwt_identity()
  # ownership baked into the query — no bypass possible
  order = Order.query.filter_by(id=order_id, user_id=current_uid).first_or_404()
  return jsonify(order.to_dict())

# Use UUID v4 instead of SERIAL to slow enumeration:
CREATE TABLE orders (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, ...)

